let globalVar = "Я глобальная";

function outer() {
    let outerVar = "Я во внешней функции";

    function inner() {
        let innerVar = "Я во внутренней функции";

        // Видим всё: innerVar, outerVar, globalVar
        console.log(innerVar);  // ✅
        console.log(outerVar);  // ✅ (из внешней области)
        console.log(globalVar); // ✅ (глобальная)
    }

    inner();
    // console.log(innerVar); // ❌ ReferenceError!
}

outer();

function createCounter() {
    let count = 0; // Эта переменная «запомнится»

    return function() {
        count++; // Функция обращается к count из внешней области
        return count;
    };
}

const counter = createCounter();
console.log(counter()); // 1
console.log(counter()); // 2
console.log(counter()); // 3

function createBankAccount(initialBalance) {
    let balance = initialBalance; // Приватная переменная

    return {
        deposit(amount) {
            balance += amount;
            return `Баланс: ${balance}`;
        },
        withdraw(amount) {
            if (amount > balance) return "Недостаточно средств";
            balance -= amount;
            return `Баланс: ${balance}`;
        },
        getBalance() {
            return balance;
        }
    };
}

const account = createBankAccount(1000);
console.log(account.deposit(500));    // "Баланс: 1500"
console.log(account.withdraw(200));   // "Баланс: 1300"

